public class PluginManagerTest : AbstractGhidraHeadedIntegrationTest {

	private TestEnv env;
	private PluginTool tool;

	/* @Before */
	public void setUp()
    {
		env = new TestEnv();
		tool = env.getTool();
		runSwing(() => tool.setConfigChanged(false));
	}

	/* @After */
